import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Authorization","description":"Authorization reference documentation","frontmatter":{"title":"Authorization","description":"Authorization reference documentation"},"headers":[],"relativePath":"knowledge/authorization.md","filePath":"knowledge/authorization.md","lastUpdated":1784485118000}'),r={name:"knowledge/authorization.md"};function n(o,e,l,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h1><h1 id="authorization-patterns-—-knowledge-base" tabindex="-1">Authorization Patterns — Knowledge Base <a class="header-anchor" href="#authorization-patterns-—-knowledge-base" aria-label="Permalink to &quot;Authorization Patterns — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Authorization determines what an authenticated user is allowed to do. This knowledge base covers authorization models, implementation patterns in Next.js/Supabase applications, and strategies for enforcing access control at every layer of the application stack.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="authorization-models" tabindex="-1">Authorization Models <a class="header-anchor" href="#authorization-models" aria-label="Permalink to &quot;Authorization Models&quot;">​</a></h3><p><strong>Role-Based Access Control (RBAC)</strong> Users are assigned roles; roles define permissions. Simple, widely understood, and sufficient for most applications.</p><ul><li>Example: <code>admin</code>, <code>editor</code>, <code>viewer</code> roles with associated permission sets</li><li>Scales by adding roles, not individual permissions</li></ul><p><strong>Attribute-Based Access Control (ABAC)</strong> Access decisions based on attributes of users, resources, and environment. More flexible than RBAC but complex to implement.</p><ul><li>Example: &quot;Allow access if user.department === resource.department AND time is during business hours&quot;</li><li>Policy engines like Open Policy Agent (OPA) evaluate attributes</li></ul><p><strong>Permission-Based Access Control (PBAC)</strong> Fine-grained permissions attached directly to users or resources. Combines flexibility of ABAC with simplicity.</p><ul><li>Example: <code>user:123:read:document:456</code> — specific user, specific action, specific resource</li></ul><h3 id="role-hierarchy" tabindex="-1">Role Hierarchy <a class="header-anchor" href="#role-hierarchy" aria-label="Permalink to &quot;Role Hierarchy&quot;">​</a></h3><p>Roles can inherit permissions from parent roles, forming a tree structure.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>super_admin</span></span>
<span class="line"><span>  └── admin</span></span>
<span class="line"><span>        ├── editor</span></span>
<span class="line"><span>        │     └── viewer</span></span>
<span class="line"><span>        └── moderator</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Inherited permissions reduce duplication; a user with <code>admin</code> role automatically has <code>editor</code> and <code>viewer</code> permissions.</p><h3 id="permission-model" tabindex="-1">Permission Model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission Model&quot;">​</a></h3><p>Permissions consist of three components:</p><ul><li><strong>Subject</strong> — Who is requesting (user, role, group)</li><li><strong>Action</strong> — What operation (create, read, update, delete, manage)</li><li><strong>Resource</strong> — What is being accessed (document, user, settings)</li></ul><p>Permission checks evaluate: <code>can(subject, action, resource) → boolean</code></p><h3 id="row-level-security-rls" tabindex="-1">Row-Level Security (RLS) <a class="header-anchor" href="#row-level-security-rls" aria-label="Permalink to &quot;Row-Level Security (RLS)&quot;">​</a></h3><p>Database-level authorization that filters rows based on the requesting user&#39;s identity. Supabase/PostgreSQL RLS policies execute as part of every query.</p><p><strong>RLS policy structure:</strong></p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> POLICY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;users_can_read_own_orders&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  FOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="middleware-based-authorization" tabindex="-1">Middleware-Based Authorization <a class="header-anchor" href="#middleware-based-authorization" aria-label="Permalink to &quot;Middleware-Based Authorization&quot;">​</a></h3><p>Next.js middleware runs before route handlers, providing a centralized authorization checkpoint at the edge.</p><h3 id="resource-level-access-control" tabindex="-1">Resource-Level Access Control <a class="header-anchor" href="#resource-level-access-control" aria-label="Permalink to &quot;Resource-Level Access Control&quot;">​</a></h3><p>Fine-grained control over individual resources, not just resource types. Users may own specific documents, not just have &quot;read documents&quot; permission.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Centralize authorization logic</strong> — Never scatter permission checks across components; use middleware, API guards, or a shared authorization service</li><li><strong>Implement deny-by-default</strong> — All access is denied unless explicitly granted; add permissions positively rather than removing denials</li><li><strong>Use Supabase RLS for data-level access</strong> — RLS policies enforce access at the database level, preventing data leakage even if application code has bugs</li><li><strong>Separate authentication from authorization</strong> — Verify identity (authN) first, then check permissions (authZ); don&#39;t combine these checks</li><li><strong>Validate authorization on every API call</strong> — Client-side UI hiding is not security; every endpoint must independently verify permissions</li><li><strong>Use principle of least privilege</strong> — Users get minimum required permissions; promote explicitly rather than giving broad access by default</li><li><strong>Implement audit logging for access control</strong> — Log who accessed what, when, and whether access was granted or denied; essential for compliance</li><li><strong>Cache authorization decisions carefully</strong> — Permissions change; use short TTLs (seconds to minutes) and invalidate on role/permission changes</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Checking permissions only in the UI</strong> — Hiding buttons without server-side enforcement means any API call bypasses authorization; always enforce server-side</li><li><strong>Using client-provided user IDs for access control</strong> — Never trust the client to declare who they are; extract user identity from verified tokens or session</li><li><strong>Hardcoding role names in conditionals</strong> — Scattered <code>if (role === &#39;admin&#39;)</code> checks are fragile and inconsistent; use a centralized permission system</li><li><strong>Granting superadmin access for convenience</strong> — Administrative shortcuts create security risks; use scoped test accounts instead</li><li><strong>Ignoring tenant isolation in multi-tenant apps</strong> — Every query must be scoped to the tenant; missing this causes data leakage between organizations</li><li><strong>Using OR logic when combining access rules</strong> — Multiple access conditions with OR can over-permit; prefer AND logic that requires all conditions to be met</li><li><strong>Not handling permission changes in real-time</strong> — If a user&#39;s role changes, active sessions must reflect new permissions; invalidate cached permissions</li><li><strong>Exposing internal resource identifiers</strong> — UUIDs in URLs can still be enumerated; combine with RLS so even correct IDs don&#39;t grant unauthorized access</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Forgetting RLS policies on new tables</strong> — Every new Supabase table should have RLS enabled and policies defined before deployment</li><li><strong>Using service role key for user operations</strong> — <code>SUPABASE_SERVICE_ROLE_KEY</code> bypasses RLS; only use for legitimate server-side admin tasks</li><li><strong>Not handling role changes during active sessions</strong> — When admin revokes a user&#39;s role, the user&#39;s current session should be invalidated or re-validated</li><li><strong>Over-relying on middleware for authorization</strong> — Middleware checks route-level access but not resource-level; combine with RLS or handler-level checks</li><li><strong>Leaking data through error messages</strong> — &quot;Document not found&quot; vs &quot;Access denied&quot; reveals whether a resource exists; return the same message for both cases</li><li><strong>Forgetting about read vs write permissions</strong> — Read access doesn&#39;t imply write access; always check the specific action being performed</li><li><strong>Not implementing organizational scoping</strong> — Multi-tenant apps must scope every query to the organization; missing this causes cross-tenant data exposure</li><li><strong>Using JWT claims without server-side verification</strong> — Client-side JWT manipulation is trivial; always verify tokens server-side before trusting claims</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommended Approach</th></tr></thead><tbody><tr><td>Simple CRUD app</td><td>RBAC with 3-5 roles + Supabase RLS</td></tr><tr><td>Multi-tenant SaaS</td><td>RLS with tenant_id column + organization middleware</td></tr><tr><td>Complex permissions (healthcare/finance)</td><td>ABAC or PBAC with policy engine</td></tr><tr><td>Admin panel</td><td>RBAC with role hierarchy + audit logging</td></tr><tr><td>Public API with rate limits</td><td>API key authentication + scope-based authorization</td></tr><tr><td>Content management system</td><td>Resource-level ownership + role-based access</td></tr><tr><td>Real-time collaborative apps</td><td>Permission checks on every WebSocket event</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Supabase RLS Documentation: <a href="https://supabase.com/docs/guides/auth/row-level-security" target="_blank" rel="noreferrer">https://supabase.com/docs/guides/auth/row-level-security</a></li><li>NIST RBAC Standard (ANSI/INCITS 359-2001)</li><li>OWASP Authorization Cheat Sheet: <a href="https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html" target="_blank" rel="noreferrer">https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html</a></li><li>Open Policy Agent: <a href="https://www.openpolicyagent.org/" target="_blank" rel="noreferrer">https://www.openpolicyagent.org/</a></li><li>Casbin (Authorization Library): <a href="https://casbin.org/" target="_blank" rel="noreferrer">https://casbin.org/</a></li><li>Next.js Middleware Documentation: <a href="https://nextjs.org/docs/app/building-your-application/routing/middleware" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/routing/middleware</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Supabase RLS setup:</strong> Enable RLS on every table immediately; create migration files with policies alongside table creation</li><li><strong>Middleware pattern:</strong> Use Next.js middleware to check authentication; use Supabase RLS for authorization — these are complementary layers</li><li><strong>Testing authorization:</strong> Write tests that verify User A cannot access User B&#39;s resources; test role transitions and permission boundary cases</li><li><strong>Migration strategy:</strong> When introducing authorization to an existing app, start with RLS policies, then add API-level checks, then UI restrictions</li><li><strong>Performance:</strong> RLS adds minimal overhead (microseconds per query); middleware authorization runs at the edge with negligible latency</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,42)])])}const g=s(r,[["render",n]]);export{u as __pageData,g as default};
